begin;
-- Fonte: Plano de Contas BP.xlsx fornecido pelo usuário. Somente cadastro, sem saldos.
-- 173 contas: 59 sintéticas, 114 analíticas; 26 chaves, exclusivamente nas analíticas.
do $$ begin
 if not exists(select 1 from public.organizations where id='0070482f-c2d5-4766-b20a-0549a7984e94' and name='Marcher Brasil') then raise exception 'Organização Marcher Brasil não encontrada'; end if;
end $$;
on conflict (organization_id,account_code) do update set
 name=excluded.name,node_class=excluded.node_class,group_key=excluded.group_key,source_name=excluded.source_name,
 source_row=excluded.source_row,sort_order=excluded.sort_order,active=excluded.active,
 parent_id=(select p.id from public.bp_plan_nodes p where p.organization_id=excluded.organization_id and p.account_code=(select x.account_code from public.bp_plan_nodes x where x.id=excluded.parent_id));
commit;
select count(*) as total, count(*) filter(where node_class='Sintetica') as sinteticas,
 count(*) filter(where node_class='Analitica') as analiticas,
 count(distinct group_key) filter(where node_class='Analitica') as chaves_agrupadoras,
 count(*) filter(where node_class='Sintetica' and group_key is not null) as sinteticas_com_chave
from public.bp_plan_nodes where organization_id='0070482f-c2d5-4766-b20a-0549a7984e94';
